+impl ScreenCapture {
+    pub fn display_info() -> Result<DisplayInfo, CaptureError> {
+        Err(CaptureError::Unsupported)
+    }
+
+    pub fn start(
+        _config: CaptureConfig,
+    ) -> Result<(Self, mpsc::Receiver<CaptureEvent>), CaptureError> {
+        Err(CaptureError::Unsupported)
+    }
+
+    pub fn stop(self) -> Result<(), CaptureError> {
